mapper.select:
SELECT i.item_id, i.item_name, i.item_brand, i.item_price, i.item_category, i.item_type, ii.item_url FROM item i LEFT JOIN item_img ii ON i.item_id = ii.item_id AND ii.is_main = 'Y' WHERE 1=1
AND i.item_type = #{type}
ORDER BY i.item_price DESC ORDER BY i.item_price ASC ORDER BY i.item_id DESC
